          "code": "import numpy as np\nfrom scipy import stats\nimport matplotlib.pyplot as plt\n\n\ndef analyze_process(mu=0, sigma=1, sample_size=1000, num_samples=5, seed=0):\n    \"\"\"\n    Analyze a manufacturing process that produces parts following a normal\n    distribution N(mu, sigma^2).\n\n    The function generates `num_samples` independent samples of size\n    `sample_size` from the distribution, computes the empirical mean and\n    standard deviation of each sample, plots the histogram of every sample\n    together with the theoretical probability density function on the same\n    Axes, and computes the overall empirical mean and standard deviation\n    across all samples (i.e. over all pooled observations).\n\n    Parameters:\n    - mu (float): The mean of the normal distribution. Default is 0.\n    - sigma (float): The standard deviation of the normal distribution. Default is 1.\n    - sample_size (int): The size of each sample to generate. Default is 1000.\n    - num_samples (int): The number of samples to generate. Default is 5.\n    - seed (int): The seed for the random number generator. Default is 0.\n\n    Returns:\n    - ax (matplotlib.axes._axes.Axes): Axes object with the plotted histograms\n      and the probability density function of the normal distribution.\n    - empirical_means (list of float): The empirical mean of each sample.\n    - empirical_stds (list of float): The empirical standard deviation of each sample.\n    - overall_mean (float): The overall empirical mean across all samples.\n    - overall_std (float): The overall empirical standard deviation across all samples.\n    \"\"\"\n    np.random.seed(seed)\n\n    empirical_means = []\n    empirical_stds = []\n    all_samples = []\n\n    fig, ax = plt.subplots()\n\n    x = np.linspace(mu - 4 * sigma, mu + 4 * sigma, 1000)\n    ax.plot(x, stats.norm.pdf(x, mu, sigma), 'r-', lw=2,\n            label='Theoretical PDF')\n\n    for i in range(num_samples):\n        sample = np.random.normal(mu, sigma, sample_size)\n        all_samples.append(sample)\n\n        empirical_mean = sample.mean()\n        empirical_std = sample.std()\n        empirical_means.append(empirical_mean)\n        empirical_stds.append(empirical_std)\n\n        ax.hist(sample, bins=30, density=True, alpha=0.6,\n                edgecolor='black', label='Sample {}'.format(i + 1))\n\n    all_data = np.concatenate(all_samples)\n    overall_mean = all_data.mean()\n    overall_std = all_data.std()\n\n    ax.set_title('Normal Distribution with $\\\\mu = %0.2f, \\\\sigma = %0.2f$'\n                 % (mu, sigma))\n    ax.set_xlabel('Value')\n    ax.set_ylabel('Density')\n    ax.legend()\n\n    return ax, empirical_means, empirical_stds, overall_mean, overall_std\n"
